/**
 * A collapsible section showing the model's reasoning (`design/components/reasoning-disclosure.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/reasoning-disclosure.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/collapsible'
import { normalizeProps } from '@zag-js/solid'

import {
  Icon,
  agentMember,
  claimSlot,
  classes,
  createDerived,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/reasoning-disclosure.module.css'

export interface ReasoningDisclosureProps {
  /**
   * The reasoning, as a `Markdown size="sm"` or a `StreamingText size="sm"`.
   */
  children: JSX.Element
  /**
   * Whether it starts open, closed by default so the reasoning is available but out of the way.
   */
  defaultOpen?: boolean
  /**
   * The trigger's text in the app's words, such as "Thinking…" or "Thought for 12 seconds".
   */
  label: string
  onOpenChange?: (open: boolean) => void
  /**
   * The controlled open state, paired with `onOpenChange` as in Radix.
   */
  open?: boolean
  /**
   * Whether the model is still reasoning, which spins the mark and sets `aria-busy` on the root.
   */
  streaming?: boolean
}

/** A collapsible section showing the model's reasoning. */
export default function ReasoningDisclosure(given: ReasoningDisclosureProps): JSX.Element {
  const props = mergeProps(
    { streaming: false, defaultOpen: false } as Defaults<
      ReasoningDisclosureProps,
      'streaming' | 'defaultOpen'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const trigger = elementRef<HTMLElement>()
    const documentDirection = useDirection(() => trigger.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open,
          defaultOpen: props.defaultOpen,
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'ReasoningDisclosure',
        element: () => trigger.value,
        state: () => ({ expanded: api.value.open, streaming: props.streaming }),
        actions: {
          expand: () => api.value.setOpen(true),
          collapse: () => api.value.setOpen(false),
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <div
        {...mergeParts(api.value.getRootProps(), {
          class: styles.root,
          'data-streaming': props.streaming ? '' : undefined,
          'aria-busy': props.streaming ? true : undefined,
          'data-member': 'reasoning-disclosure',
        })}
      >
        {/* trigger */}
        <button
          {...mergeParts(api.value.getTriggerProps(), { class: styles.trigger })}
          ref={trigger.attach}
        >
          {/* mark */}
          <span class={classes(styles.mark, props.streaming ? styles.spinning : undefined)}>
            <Icon name={props.streaming ? 'loading' : 'reasoning'} size="sm" />
          </span>
          {/* label */}
          <span class={styles.label}>{props.label}</span>
          {/* chevron */}
          <span class={styles.chevron}>
            <Icon name="down" size="sm" />
          </span>
        </button>
        {/* content */}
        <div
          {...mergeParts(api.value.getContentProps(), {
            class: styles.content,
            style: {
              '--radix-collapsible-content-height': Object(api.value.getContentProps().style)[
                '--height'
              ],
            },
          })}
        >
          <div class={styles.inner}>{props.children}</div>
        </div>
      </div>
    )
  })
}
